const content = $input.first().json.patchContent;

// Clean up the content but keep structure
let cleanContent = content
  .replace(/From OpenEMR Project Wiki/gi, '')
  .replace(/Retrieved from.*$/gm, '')
  .replace(/Categories:.*$/gm, '')
  .replace(/\[edit\]/g, '')
  .trim();

// Extract version - try multiple patterns
let version = 'Unknown Version';

// Pattern 1: "OpenEMR 7.0.3 Patches" or "7.0.3 Patches"
const versionMatch1 = cleanContent.match(/OpenEMR\s+([\d.]+)\s+Patches?/i);
if (versionMatch1) {
  version = versionMatch1[1];
} else {
  // Pattern 2: Just version number followed by Patches
  const versionMatch2 = cleanContent.match(/([\d.]+)\s+Patches?/i);
  if (versionMatch2) {
    version = versionMatch2[1];
  } else {
    // Pattern 3: Look for version in title or heading
    const versionMatch3 = cleanContent.match(/version\s+([\d.]+)/i);
    if (versionMatch3) {
      version = versionMatch3[1];
    } else {
      // Pattern 4: Just find any version-like number
      const versionMatch4 = cleanContent.match(/([\d]+\.[\d]+\.[\d]+)/i);
      if (versionMatch4) {
        version = versionMatch4[1];
      }
    }
  }
}

// Try to extract patch listings
const patchSections = [];
const lines = cleanContent.split('\n');
for (let i = 0; i < lines.length; i++) {
  const line = lines[i].trim();
  if (line.match(/^Patch\s+\d+/i) || line.match(/^\d+\./)) {
    patchSections.push(line);
  } else if (line.length > 20 && line.match(/sql|fix|update|bug|security/i)) {
    patchSections.push(line);
  }
}

const patchList = patchSections.length > 0 
  ? patchSections.slice(0, 20).join('\n') 
  : cleanContent.substring(0, 2000);

// Check if there are patches
const hasPatches = !cleanContent.includes('no 7.0.4 patches yet') && 
                   !cleanContent.includes('There are no') &&
                   cleanContent.length > 100;

return {
  json: {
    cleanContent,
    patchList,
    version,
    hasPatches,
    timestamp: new Date().toISOString(),
    patchCount: patchSections.length
  }
};

// Simple hash function since crypto module is disabled
function simpleHash(str) {
  let hash = 0;
  if (str.length === 0) return hash.toString();
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash; // Convert to 32bit integer
  }
  return Math.abs(hash).toString(36);
}

// Get the input data directly from Process Content
const inputData = $input.first().json;

// Generate hash using simple function
const currentHash = simpleHash(inputData.cleanContent || '');

// Try to get previous hash from static data
let previousHash = 'initial';
try {
  const staticData = $workflow.staticData;
  if (staticData && staticData.lastHash) {
    previousHash = staticData.lastHash;
  }
} catch (e) {
  previousHash = 'initial';
}

// Check if content has changed
const hasChanged = currentHash !== previousHash;

console.log('Hash Check:', {
  currentHash,
  previousHash,
  hasChanged
});

// Return all data needed for email
return {
  json: {
    currentHash: currentHash,
    previousHash: previousHash,
    hasChanged: hasChanged,
    cleanContent: inputData.cleanContent || 'No content',
    patchList: inputData.patchList || 'No patches listed',
    version: inputData.version || 'Unknown',
    patchCount: inputData.patchCount || 0,
    timestamp: inputData.timestamp || new Date().toISOString()
  }
};

// Update the stored hash in workflow static data
const currentHash = $input.first().json.currentHash;

try {
  if (!$workflow.staticData) {
    $workflow.staticData = {};
  }
  $workflow.staticData.lastHash = currentHash;
} catch (e) {
  console.log('Could not save to static data:', e);
}

return {
  json: {
    message: 'Hash updated successfully',
    newHash: currentHash,
    timestamp: new Date().toISOString()
  }
};

// Just pass through - no changes detected
return {
  json: {
    message: 'No changes detected',
    hash: $input.first().json.currentHash,
    timestamp: new Date().toISOString()
  }
};
